(() => {
  const KEY = 'barakah-habit-tracker-v1';
  const iconSet = ['☾','◉','✦','♡','⌁','☼','✧','❋','⌂','◌','❀','◈'];
  const seed = [
    {id:'fajr',name:'Fajr prayer',category:'Prayer',goal:'On time',icon:'☾'},
    {id:'quran',name:'Read Qur’an',category:'Qur’an',goal:'10 minutes',icon:'◉'},
    {id:'dhikr',name:'Morning adhkar',category:'Dhikr',goal:'After Fajr',icon:'✦'},
    {id:'kindness',name:'An act of kindness',category:'Character',goal:'Big or small',icon:'♡'},
    {id:'learn',name:'Learn something beneficial',category:'Learning',goal:'A few minutes',icon:'⌁'}
  ];
  const today = new Date();
  let state = load();
  state.appearance = state.appearance === 'dark' ? 'dark' : 'light';
  let selectedDate = dayKey(today);
  let activeView = 'today';
  let learnSection = 'hub', editingNoteId = null;
  let dhikrGroup = 'morning', dhikrCollection = '', dhikrSearch = '', duaCategory = 'All', duaSearch = '';
  let adhkarRecords = null, adhkarPromise = null, adhkarError = '';
  let propheticCollection = null, propheticPromise = null, propheticError = '';
  let duaChapters = null, duaChaptersPromise = null, duaEntries = [], duaSelectedChapter = '', duaEntryDetail = null, duaLoading = false, duaError = '', duaSearchResults = null, duaSearchRequested = '', duaSearchTimer = null;
  let editingId = null;
  let selectedIcon = iconSet[0];
  let toastTimer;
  const $ = (s,root=document) => root.querySelector(s);
  const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function dayKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function load(){if(window.BARAKAH_INITIAL_STATE)return JSON.parse(JSON.stringify(window.BARAKAH_INITIAL_STATE));try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.habits)&&v.logs)return v}catch{}return {habits:seed,logs:{}}}
  function save(){if(!window.BARAKAH_USER)localStorage.setItem(KEY,JSON.stringify(state));if(window.BARAKAH_PERSIST)window.BARAKAH_PERSIST(state).then(({error})=>{if(error)toast('Cloud sync failed. Your latest changes may not be saved.')}).catch(()=>toast('Cloud sync failed. Your latest changes may not be saved.'))}
  window.BARAKAH_SAVE_STATE=save;
  function fmtDate(d,opt={weekday:'long',month:'long',day:'numeric'}){return d.toLocaleDateString(undefined,opt)}
  function selected(){const [y,m,d]=selectedDate.split('-').map(Number);return new Date(y,m-1,d)}
  function getStatus(date,id){return state.logs[date]?.[id]||''}
  function setStatus(date,id,status){state.logs[date] ||= {}; if(status)state.logs[date][id]=status;else delete state.logs[date][id];save()}
  function completedCount(date){return state.habits.filter(h=>getStatus(date,h.id)==='done').length}
  function streak(id){let d=new Date();let n=0;for(let i=0;i<366;i++){const k=dayKey(d);if(getStatus(k,id)!=='done')break;n++;d.setDate(d.getDate()-1)}return n}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
  function render(){
    document.documentElement.dataset.theme=state.appearance;
    $('#top-date').textContent=fmtDate(today,{month:'short',day:'numeric',year:'numeric'});
    const titles={today:'HOME',quran:'QUR’AN',insights:'INSIGHTS',habits:'HABITS',rewards:'REWARDS',profile:'PROFILE',learn:'LEARN & REMEMBER'};$('#section-title').textContent=titles[activeView]||'HOME';
    document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));
    const user=window.BARAKAH_USER;if(user){const name=user.user_metadata?.full_name||user.email?.split('@')[0]||'My journey';$('.profile-name').textContent=name;$('.profile-mark').textContent=arabicInitial(name);$('.profile').setAttribute('aria-label',`Open profile of ${name}`);$('.profile-launch').setAttribute('aria-label',`Open profile of ${name}`)}
    const container=$('#view-container');
    if(activeView==='today')container.innerHTML=renderToday();
    if(activeView==='quran')container.innerHTML=window.BarakahSpiritual.renderQuran(state);
    if(activeView==='insights')container.innerHTML=renderInsights();
    if(activeView==='habits')container.innerHTML=renderHabits();
    if(activeView==='rewards')container.innerHTML=window.BarakahRewards.render(state,window.BARAKAH_USER);
    if(activeView==='profile')container.innerHTML=renderProfile();
    if(activeView==='learn')container.innerHTML=renderLearn();
    bindView();
    if(activeView==='quran')window.BarakahSpiritual.bindQuran({state,render,toast});
    if(activeView==='today')window.BarakahSpiritual.bindHome({state,render,toast});
    if(activeView==='learn'&&learnSection==='dhikr')window.BarakahSpiritual.bindDhikr({state,render,toast});
    if(activeView==='learn')bindLearn();
    if(activeView==='profile')window.BarakahSpiritual.bindProfile({state,render,toast});
    if(activeView==='rewards')window.BarakahRewards.bind({state,render,toast});
    if(activeView==='insights')drawChart();
  }
  function renderToday(){
    const date=selected(), key=selectedDate, done=completedCount(key), total=state.habits.length, pct=total?Math.round(done/total*100):0;
    const isToday=key===dayKey(today);
    const dailyNote=window.BarakahSpiritual.dailyNote(new Date());
    const habitHtml=state.habits.map((h,i)=>{const status=getStatus(key,h.id);return `<article class="habit-card stagger"><div class="habit-symbol">${esc(h.icon)}</div><div class="habit-info"><strong>${esc(h.name)}</strong><span>${esc(h.goal||h.category)}</span></div><div class="habit-meta"><span class="habit-streak">${streak(h.id)?`<b>✦ ${streak(h.id)}</b> day streak`:''}</span><button class="check-button ${status}" data-check="${esc(h.id)}" aria-label="${status==='done'?'Mark incomplete':'Mark complete'}: ${esc(h.name)}" title="Click to mark complete">${status==='done'?'✓':status==='partial'?'•':''}</button></div></article>`}).join('');
    return `<div class="page"><div class="greeting-row"><div><span class="eyebrow">A MOMENT FOR WHAT MATTERS</span><h1>${isToday?greeting():fmtDate(date,{weekday:'long'})}<span>.</span></h1><p class="subheading">Show up with intention. Every small step counts.</p></div><div class="day-controls"><button class="day-nav" data-day="-1" aria-label="Previous day">‹</button><span class="day-label">${isToday?'Today':fmtDate(date,{month:'short',day:'numeric'})}</span><button class="day-nav" data-day="1" aria-label="Next day" ${isToday?'disabled':''}>›</button></div></div>
      <section class="streak-banner"><div class="streak-icon">✦</div><div class="streak-copy"><strong>${done===total&&total?'A beautiful day of showing up.':'Your journey, one intention at a time.'}</strong><p>${done===total&&total?'Alhamdulillah — you honored every intention today.':'There is no perfect day. Just the next good choice.'}</p></div><div class="streak-count"><strong>${longestCurrentStreak()}</strong><span>DAY STREAK</span></div></section>
      <button class="learn-entry" data-goto="learn"><span class="learn-entry-mark">✧</span><span class="learn-entry-copy"><strong>Learn &amp; Remember</strong><small>Hadith, dhikr, du’a, and your notes</small></span><span class="learn-entry-arrow">↗</span></button>
      <div class="section-heading"><div><h2>Your intentions</h2><p>${isToday?'A gentle check-in for today':`A look back at ${fmtDate(date,{month:'long',day:'numeric'})}`}</p></div><button class="text-button" data-goto="habits">Manage habits ↗</button></div>
      <div class="habit-list">${habitHtml||`<div class="empty-state"><div class="empty-icon">✧</div><h3>Begin with an intention</h3><p>Add a spiritual practice that feels meaningful to you. You can adjust it whenever your journey changes.</p><button class="button primary" data-action="add">Add your first habit <span>↗</span></button></div>`}</div>
      ${total?`<section class="progress-strip"><div><div class="progress-copy"><span>Today’s progress</span><strong>${done} of ${total} intentions</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div><div class="progress-ring" style="--progress:${pct*3.6}deg"><span>${pct}%</span></div></section>`:''}
      ${window.BarakahSpiritual.renderHome(state)}
      <div class="section-heading"><div><h2>A note for today</h2><p>A fresh reflection each day</p></div></div><div class="panel daily-note-card" style="padding:15px 17px"><div class="insight-note" style="margin:0"><span>☼</span><p><strong>${esc(dailyNote.title)}</strong> ${esc(dailyNote.body)}</p></div></div>
    </div>`;
  }
  function greeting(){const user=window.BARAKAH_USER;const name=user?.user_metadata?.full_name?.trim()||user?.email?.split('@')[0]||'friend';return `As-salāmu ʿalaykum, ${esc(name)}`}
  function arabicInitial(name){const first=Array.from(String(name||'').trim())[0]||'ب';if(/[\u0600-\u06ff]/.test(first))return first;return ({a:'ا',b:'ب',c:'ك',d:'د',e:'إ',f:'ف',g:'ج',h:'ه',i:'إ',j:'ج',k:'ك',l:'ل',m:'م',n:'ن',o:'و',p:'ب',q:'ق',r:'ر',s:'س',t:'ت',u:'و',v:'ف',w:'و',x:'خ',y:'ي',z:'ز'})[first.toLowerCase()]||'ب'}
  function longestCurrentStreak(){return window.BarakahRewards.currentStreak(state)}
  const hadithBooks=[
    {id:'bukhari',name:'Sahih al-Bukhari',subtitle:'A foundational collection of the Prophet’s teachings',url:'https://sunnah.com/bukhari',mark:'ب'},
    {id:'muslim',name:'Sahih Muslim',subtitle:'A major collection of rigorously transmitted hadith',url:'https://sunnah.com/muslim',mark:'م'},
    {id:'tirmidhi',name:'Jamiʿ at-Tirmidhi',subtitle:'Hadith with chapter headings and grading notes',url:'https://sunnah.com/tirmidhi',mark:'ت'}
  ];
  function learnHeader(title,subtitle){return `<div class="learn-subhead"><button class="button secondary" data-learn-back>← Learn &amp; Remember</button><div><span class="eyebrow">A QUIET PLACE TO GROW</span><h1>${title}<span style="color:#9eaa74">.</span></h1><p class="subheading">${subtitle}</p></div></div>`}
  function renderLearn(){
    if(learnSection==='hub')return `<div class="page"><div class="page-title"><div><span class="eyebrow">A QUIET PLACE TO GROW</span><h1>Learn &amp; Remember<span style="color:#9eaa74">.</span></h1><p class="subheading">Explore prophetic guidance, remembrance, supplication, and personal reflection.</p></div></div><div class="learn-grid"><button class="learn-card" data-learn-section="hadith"><span class="learn-card-icon">۞</span><strong>Hadith</strong><span>Explore three major hadith collections</span><b>Open collections ↗</b></button><button class="learn-card" data-learn-section="dhikr"><span class="learn-card-icon">✦</span><strong>Dhikr</strong><span>Morning and evening adhkar, plus supplications narrated from the Prophets</span><b>Open dhikr ↗</b></button><button class="learn-card" data-learn-section="dua"><span class="learn-card-icon">☾</span><strong>Du’a</strong><span>Browse the full sourced Hisn al-Muslim collection</span><b>Browse du’a ↗</b></button><button class="learn-card" data-learn-section="notes"><span class="learn-card-icon">✎</span><strong>Notes</strong><span>Keep private reflections with your account</span><b>Open notes ↗</b></button></div><div class="learn-footnote">Your personal notes and dhikr counters save with your Barakah account.</div></div>`;
    if(learnSection==='hadith')return `<div class="page">${learnHeader('Hadith collections','Choose a collection to open its full book index on Sunnah.com.')}<div class="book-grid">${hadithBooks.map(book=>`<a class="book-card" href="${book.url}" target="_blank" rel="noopener noreferrer"><span class="book-mark">${book.mark}</span><span class="book-copy"><strong>${book.name}</strong><small>${book.subtitle}</small></span><span class="book-arrow">↗</span><span class="book-source">Verified collection at Sunnah.com</span></a>`).join('')}</div><p class="learn-source-note">The selected collection opens in a new tab so its full text, chapters, and references remain attributed to the source.</p></div>`;
    if(learnSection==='dhikr')return renderDhikrLearn();
    if(learnSection==='dua')return renderDuaLearn();
    if(learnSection==='notes')return renderLearnNotes();
    return `<div class="page">${learnHeader('Learn &amp; Remember','Choose a section to continue.')}</div>`;
  }
  function loadAdhkarSource(){
    if(adhkarPromise)return adhkarPromise;
    adhkarError='';
    adhkarPromise=window.BarakahContent.loadAdhkar().then(records=>{adhkarRecords=records;return records}).catch(error=>{adhkarError=error.message||'Could not load the adhkar source.';adhkarPromise=null;throw error});
    return adhkarPromise;
  }
  function loadDuaChapters(){
    if(duaChaptersPromise)return duaChaptersPromise;
    duaError='';
    duaChaptersPromise=window.BarakahContent.loadDuaChapters().then(chapters=>{duaChapters=chapters;return chapters}).catch(error=>{duaError=error.message||'Could not load the Hisn al-Muslim collection.';duaChaptersPromise=null;throw error});
    return duaChaptersPromise;
  }
  function loadDuaEntries(chapterId){
    duaSelectedChapter=chapterId;duaEntryDetail=null;duaLoading=true;duaError='';duaSearchResults=null;renderIfLearn();
    window.BarakahContent.loadDuaChapterEntries(chapterId).then(entries=>{if(duaSelectedChapter!==chapterId)return;duaEntries=entries;duaLoading=false;renderIfLearn()}).catch(error=>{if(duaSelectedChapter!==chapterId)return;duaLoading=false;duaError=error.message||'Could not load this chapter.';renderIfLearn()});
  }
  function loadDuaDetail(id){
    duaLoading=true;duaEntryDetail=null;duaError='';renderIfLearn();
    window.BarakahContent.loadDuaEntry(id).then(entry=>{duaEntryDetail=entry;duaLoading=false;renderIfLearn()}).catch(error=>{duaLoading=false;duaError=error.message||'Could not load this supplication.';renderIfLearn()});
  }
  function searchDuaSource(query){
    const term=query.trim();if(!term){duaSearchResults=null;duaSearchRequested='';duaLoading=false;return renderIfLearn()}
    duaSearchRequested=term;duaSearchResults=null;duaLoading=true;duaError='';renderIfLearn();
    window.BarakahContent.searchDuas(term).then(entries=>{if(duaSearchRequested!==term)return;duaSearchResults=entries;duaLoading=false;renderIfLearn()}).catch(error=>{if(duaSearchRequested!==term)return;duaLoading=false;duaError=error.message||'Could not search the supplication source.';renderIfLearn()});
  }
  function renderIfLearn(){if(activeView==='learn')render()}
  function renderSourceError(message,retryAttribute){return `<div class="empty-state"><div class="empty-icon">⌁</div><h3>Couldn’t load the library</h3><p>${esc(message)}</p><button class="button secondary" ${retryAttribute}>Try again</button></div>`}
  function renderSourcedAdhkar(record,period){
    const periodKey=dayKey(today),id=`${period}-${record.order}`,target=Number(record.count)||0;
    const count=Number(state.adhkarCounts?.[periodKey]?.[id])||0,percent=target?Math.min(100,Math.round(count/target*100)):0;
    const timing=record.type===0?'Morning & evening':period==='morning'?'Morning':'Evening';
    const source=record.source||'Reference not supplied by the dataset';
    return `<article class="panel library-entry sourced-adhkar"><div class="library-entry-copy"><div class="library-entry-heading"><span class="entry-kicker">${timing} · #${record.order}</span><span class="adhkar-count-label">${target?`${target}× · ${esc(record.count_description||'recommended repetition')}`:'Count not specified'}</span></div><p class="library-arabic" lang="ar" dir="rtl">${esc(record.content)}</p>${record.transliteration?`<p class="library-translit">${esc(record.transliteration).replace(/\n/g,'<br>')}</p>`:''}<p class="library-meaning">${esc(record.translation)}</p><details class="adhkar-evidence"><summary>Timing, virtue &amp; source evidence</summary>${record.fadl?`<p><strong>Context / virtue:</strong> ${esc(record.fadl)}</p>`:''}<p><strong>Hadith or source:</strong> ${esc(source).replace(/\n/g,'<br>')}</p>${record.hadith_text?`<p class="evidence-label"><strong>Hadith text:</strong></p><p class="hadith-arabic" lang="ar" dir="rtl">${esc(record.hadith_text)}</p>${record.transliteration?`<p class="hadith-transliteration"><strong>Recitation transliteration:</strong><br>${esc(record.transliteration).replace(/\n/g,'<br>')}</p>`:''}<p class="hadith-meaning"><strong>Meaning of the adhkar:</strong> ${esc(record.translation)}</p>`:''}<p class="evidence-note">The routine label and timing details are kept as the source states them. Where a precise time is not specified in this record, none is inferred.</p></details>${record.audio?`<audio class="adhkar-audio" controls preload="none" aria-label="Listen to this dhikr"><source src="${esc(record.audio)}" type="audio/mpeg"></audio>`:''}</div><button class="library-counter" data-adhkar-count="${esc(id)}" aria-label="Count recitation of item ${record.order}: ${count}${target?` of ${target}`:''}"><span class="counter-orbit"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="19"/><circle class="counter-progress" cx="24" cy="24" r="19" style="stroke-dashoffset:${119.4-(119.4*percent/100)}"/></svg><strong>${count}</strong></span><small>${target?`of ${target}`:'Tap to count'}</small></button>${target?`<div class="entry-progress"><span style="width:${percent}%"></span></div>`:''}</article>`;
  }
  function renderOpenDuaSummary(item){
    const id=item.id||item.entryId||item.slug;
    return `<button class="library-collection dua-api-entry" data-open-dua="${esc(id)}"><span class="collection-illustration art-book">${libraryArtwork('book')}</span><span class="collection-copy"><strong>${esc(item.title||item.name||`Hisn al-Muslim ${item.sourceReference||''}`)}</strong><small>${esc(item.sourceReference?`Hisn al-Muslim · entry ${item.sourceReference}`:'Hisn al-Muslim')}</small><b>Open supplication <i>›</i></b></span></button>`;
  }
  function renderDhikrLearn(){
    const query=dhikrSearch.trim().toLocaleLowerCase();
    const groups=[['morning','Morning adhkar'],['evening','Evening adhkar'],['prophetic','Prophetic adhkars']];
    const filteredRecords=(adhkarRecords||[]).filter(record=>dhikrGroup==='morning'?Number(record.type)===0||Number(record.type)===1:dhikrGroup==='evening'?Number(record.type)===0||Number(record.type)===2:false).filter(record=>!query||`${record.content} ${record.translation} ${record.transliteration} ${record.source} ${record.fadl}`.toLocaleLowerCase().includes(query));
    const tabs=`<div class="library-tabs" role="tablist" aria-label="Dhikr routines">${groups.map(([id,label])=>`<button role="tab" aria-selected="${dhikrGroup===id}" class="${dhikrGroup===id?'selected':''}" data-dhikr-group="${id}">${label}</button>`).join('')}</div>`;
    let content='';
    if(dhikrGroup==='morning'||dhikrGroup==='evening'){
      content=adhkarRecords?`<div class="adhkar-session"><div><span class="eyebrow">${dhikrGroup==='morning'?'MORNING · SOURCE CLASSIFICATION':'EVENING · SOURCE CLASSIFICATION'}</span><h2>${dhikrGroup==='morning'?'Morning adhkar':'Evening adhkar'}</h2><p>Full routine from the selected morning/evening collection · ${filteredRecords.length} remembrances. Each item shows its source-provided repetition count and timing context; open its evidence for the hadith/source details.</p></div><div class="adhkar-session-progress"><strong>${filteredRecords.filter(record=>{const id=`${dhikrGroup}-${record.order}`;return Number(record.count)>0&&(Number(state.adhkarCounts?.[dayKey(today)]?.[id])||0)>=Number(record.count)}).length}/${filteredRecords.length}</strong><small>completed today</small></div></div><div class="library-entry-list">${filteredRecords.map(record=>renderSourcedAdhkar(record,dhikrGroup)).join('')||'<div class="empty-state"><h3>No adhkar match</h3><p>Try a shorter search term.</p></div>'}</div>`:adhkarError?renderSourceError(adhkarError,'data-retry-adhkar'): '<div class="panel content-loading"><span class="loading-spinner"></span><p>Loading the complete sourced adhkar collection…</p></div>';
    }else{
      if(propheticCollection){
        const groupsWithMatches=propheticCollection.groups.map(group=>{
          const verses=(group.loadedItems||[]).filter(item=>!query||`${group.name} ${item.key} ${item.arabic} ${item.meaning}`.toLocaleLowerCase().includes(query));
          const hadith=(group.hadith||[]).filter(item=>!query||`${group.name} ${item.arabic} ${item.meaning} ${item.source}`.toLocaleLowerCase().includes(query));
          if(!verses.length&&!hadith.length)return '';
          return `<section class="prophetic-group"><div class="prophetic-group-heading"><span class="collection-illustration art-book">${libraryArtwork('book')}</span><div><span class="eyebrow">PROPHETIC REMEMBRANCE</span><h2>${esc(group.name)}</h2><p>${verses.length} Qur’anic ${verses.length===1?'ayah':'ayahs'}${hadith.length?` · ${hadith.length} hadith ${hadith.length===1?'supplication':'supplications'}`:''}</p></div></div><div class="library-entry-list">${verses.map(item=>`<article class="panel prophetic-dua-card"><div class="prophetic-source-line"><span>Qur’an · ${esc(item.key)}</span><a href="https://quran.com/${item.key}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div><p class="dua-arabic" lang="ar" dir="rtl">${esc(item.arabic)}</p><p class="dua-meaning">${esc(item.meaning)}</p></article>`).join('')}${hadith.map(item=>`<article class="panel prophetic-dua-card"><div class="prophetic-source-line"><span>${esc(item.source)}</span><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Read hadith ↗</a></div><p class="dua-arabic" lang="ar" dir="rtl">${esc(item.arabic)}</p><p class="dua-meaning">${esc(item.meaning)}</p>${item.note?`<p class="prophetic-hadith-note">${esc(item.note)}</p>`:''}</article>`).join('')}</div></section>`;
        }).join('');
        content=`<div class="prophetic-intro"><span class="eyebrow">QUR’AN &amp; AUTHENTIC HADITH</span><h2>Supplications of the Prophets</h2><p>Browse by Prophet. Qur’anic Arabic and meanings are shown with exact ayah references; hadith reports include their collection and number. This is a curated sourced collection, not an exhaustive index. No repetition count or occasion is inferred.</p></div>${groupsWithMatches||'<div class="empty-state"><h3>No matches found</h3><p>Try a prophet name, ayah reference, or phrase.</p></div>'}`;
      }else content=propheticError?renderSourceError(propheticError,'data-retry-prophetic'):'<div class="panel content-loading"><span class="loading-spinner"></span><p>Loading cited Qur’anic and hadith supplications…</p></div>';
    }
    return `<div class="page dhikr-page">${learnHeader('Dhikr','Follow the daily morning and evening adhkar, or explore supplications transmitted from the Prophets.')}<form class="spiritual-search" data-dhikr-search-form><span>⌕</span><input name="query" type="search" value="${esc(dhikrSearch)}" placeholder="Search Arabic, meaning, prophet, or reference…" aria-label="Search dhikr"><button class="sr-only" type="submit">Search</button></form>${tabs}${window.BarakahSpiritual.renderTasbeehHistory(state)}${content}<p class="learn-source-note">Morning/evening adhkar are supplied by the <a href="https://github.com/Seen-Arabic/Morning-And-Evening-Adhkar-DB" target="_blank" rel="noopener noreferrer">Seen-Arabic Adhkar database (MIT)</a>. Prophetic Qur’anic references follow <a href="https://quran.com/duas/prophets" target="_blank" rel="noopener noreferrer">Quran.com’s Prophets collection</a>; Qur’anic text and meanings are loaded from <a href="https://alquran.cloud/api" target="_blank" rel="noopener noreferrer">Al Quran Cloud</a>. Hadith citations link to Sunnah.com. English meanings are presented for understanding.</p></div>`;
  }

  async function loadPropheticCollection(){
    if(propheticCollection||propheticPromise)return propheticPromise||propheticCollection;
    propheticError='';
    propheticPromise=window.BarakahContent.loadPropheticAdhkar().then(async source=>{
      const tasks=source.groups.flatMap(group=>group.items.map(item=>({groupId:group.id,item}))),loadedByKey=new Map();let cursor=0;
      await Promise.all(Array.from({length:Math.min(6,tasks.length)},async()=>{while(cursor<tasks.length){const task=tasks[cursor++],item=task.item;
        const response=await fetch(`https://api.alquran.cloud/v1/ayah/${encodeURIComponent(item.ayah)}/editions/quran-uthmani,en.sahih`);
        if(!response.ok)throw new Error('Qur’anic text service returned '+response.status);
        const body=await response.json();
        if(body.code!==200||!Array.isArray(body.data)||body.data.length<2)throw new Error('Qur’anic text was unavailable for '+item.ayah);
        const arabic=body.data.find(record=>record.edition?.identifier==='quran-uthmani'),meaning=body.data.find(record=>record.edition?.identifier==='en.sahih');
        if(!arabic?.text||!meaning?.text)throw new Error('Qur’anic text was incomplete for '+item.ayah);
        loadedByKey.set(task.groupId+':'+item.ayah,{key:item.ayah,arabic:arabic.text,meaning:meaning.text});
      }}));
      const groups=source.groups.map(group=>({...group,loadedItems:group.items.map(item=>loadedByKey.get(group.id+':'+item.ayah))}));
      propheticCollection={...source,groups};propheticError='';return propheticCollection;
    }).catch(error=>{propheticError=error.message||'Could not load the prophetic collection.';propheticCollection=null;throw error}).finally(()=>{propheticPromise=null});
    return propheticPromise;
  }
  function libraryArtwork(kind){
    const shapes={sun:'<circle cx="32" cy="32" r="10"/><path d="M32 5v8M32 51v8M5 32h8M51 32h8M13 13l6 6m26 26 6 6M51 13l-6 6M19 45l-6 6"/>',moon:'<path d="M42 8A23 23 0 1 0 56 43 20 20 0 0 1 42 8Z"/><path d="m18 18 2 3m21 16 2 3"/>',stars:'<path d="m32 7 4 14 14 4-14 4-4 14-4-14-14-4 14-4 4-14Zm19 29 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6Z"/>',night:'<path d="M44 9A23 23 0 1 0 56 43 20 20 0 0 1 44 9Z"/><path d="M16 50h32M22 43l5-7 5 5 7-11 7 13"/>',prayer:'<path d="M15 53h34M19 49V29h26v20M23 29a9 9 0 0 1 18 0M27 49V37h10v12M32 7v7m-8-3 3 5m10-5-3 5"/>',beads:'<circle cx="32" cy="31" r="21"/><circle cx="32" cy="10" r="2"/><circle cx="47" cy="16" r="2"/><circle cx="53" cy="31" r="2"/><circle cx="47" cy="46" r="2"/><circle cx="32" cy="52" r="2"/><circle cx="17" cy="46" r="2"/><circle cx="11" cy="31" r="2"/><circle cx="17" cy="16" r="2"/>',shield:'<path d="M32 7 51 14v14c0 13-8 21-19 27-11-6-19-14-19-27V14l19-7Z"/><path d="m24 32 6 6 12-14"/>',flower:'<circle cx="32" cy="32" r="6"/><circle cx="32" cy="17" r="7"/><circle cx="45" cy="25" r="7"/><circle cx="45" cy="40" r="7"/><circle cx="32" cy="47" r="7"/><circle cx="19" cy="40" r="7"/><circle cx="19" cy="25" r="7"/>',heart:'<path d="M32 53 11 33C-1 17 18 6 32 21 46 6 65 17 53 33L32 53Z"/><path d="M19 31h8l4-8 6 17 4-9h7"/>',book:'<path d="M8 14h18a7 7 0 0 1 7 7v31a7 7 0 0 0-7-7H8V14Zm48 0H38a5 5 0 0 0-5 7v31a7 7 0 0 1 7-7h16V14Z"/><path d="M15 23h10m-10 7h10m17-7h7m-7 7h7"/>',star:'<path d="m32 6 7 17 18 1-14 11 5 18-16-10-16 10 5-18L7 24l18-1 7-17Z"/>',sparkle:'<path d="m32 6 5 18 19 8-19 7-5 19-7-19-19-7 19-8 7-18Z"/><path d="m52 5 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6Z"/>',rain:'<path d="M18 38a12 12 0 0 1 1-24 17 17 0 0 1 32 5 10 10 0 0 1-1 19H18Z"/><path d="m23 45-3 8m17-8-3 8m17-8-3 8"/>',sunrise:'<path d="M7 48h50M13 43a19 19 0 0 1 38 0M32 8v9m-18 2 6 6m30-6-6 6M8 28h9m30 0h9"/>',cloth:'<path d="m23 9 9 5 9-5 15 9-8 12-7-4v28H19V26l-7 4-8-12 15-9Z"/><path d="M25 10a7 7 0 0 0 14 0"/>',drop:'<path d="M32 6C25 18 14 30 14 40a18 18 0 0 0 36 0C50 30 39 18 32 6Z"/><path d="M24 42a8 8 0 0 0 8 8"/>',home:'<path d="m7 29 25-21 25 21M14 25v31h36V25M26 56V38h12v18"/>',mosque:'<path d="M8 54h48M14 51V32h36v19M21 32a11 11 0 0 1 22 0M32 9v8m-4-4h8M9 51V26m0-7v4m46 28V26m0-7v4"/>',compass:'<circle cx="32" cy="32" r="23"/><path d="m41 22-5 14-14 5 5-14 14-5Z"/><path d="M32 9v4m0 38v4M9 32h4m38 0h4"/>',people:'<circle cx="24" cy="23" r="8"/><circle cx="43" cy="25" r="7"/><path d="M8 52a16 16 0 0 1 32 0m0-13a13 13 0 0 1 16 13"/>',bowl:'<path d="M9 31h46c0 15-9 24-23 24S9 46 9 31Zm7-8c2-6 6-9 11-10m13 10c-2-6-6-9-11-10"/>',travel:'<path d="m7 42 22-9 7-24 7 2-1 20 14 9-1 5-16-4-9 15-4-1 3-16-20 5-2-2Z"/>',olive:'<path d="M17 53c0-21 8-35 28-42 2 19-4 34-25 42m-3 0 25-29"/>',leaf:'<path d="M54 9C29 9 11 20 10 42c0 7 5 12 12 12 22-1 33-19 32-45Z"/><path d="M12 52 43 20m-15 13-1-10m9 3 10 1"/>',kaaba:'<path d="m12 20 20-11 20 11v34H12V20Zm0 0 20 11 20-11M32 31v23M12 35h40"/>',hands:'<path d="M12 37V24a4 4 0 0 1 8 0v8-18a4 4 0 0 1 8 0v17-20a4 4 0 0 1 8 0v20-15a4 4 0 0 1 8 0v23c0 10-7 17-18 17h-4c-9 0-14-9-18-16l-4-7a4 4 0 0 1 7-4l7 9"/>'};
    return `<svg viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${shapes[kind]||shapes.sparkle}</svg>`;
  }
  function openDuaItems(entry){
    const items=[];
    for(const variation of entry?.variations||[])for(const step of variation.steps||[])for(const item of step.items||[]){
      const dua=item.dua||((item.arabic||item.translation)?item:null);
      if(dua)items.push({dua,count:item.times||item.count||item.repeat||step.times||step.count||step.repeat,condition:variation.condition||variation.label||'',recordings:item.recordings||step.recordings||[]});
    }
    return items;
  }
  function renderOpenDuaDetail(entry){
    if(!entry)return '';
    const identity=entry.id||entry.slug||entry.sourceReference||'entry';
    const references=[...(Array.isArray(entry.references)?entry.references:[]),...openDuaItems(entry).flatMap(item=>Array.isArray(item.dua.references)?item.dua.references:[])];
    return `<section class="dua-api-detail"><div class="library-detail-head"><button class="button secondary" data-dua-detail-back>← ${duaSelectedChapter?'Back to chapter':'Back to library'}</button><div class="collection-detail-title"><span class="collection-illustration art-book">${libraryArtwork('book')}</span><div><span class="eyebrow">HISN AL-MUSLIM · ENTRY ${esc(entry.sourceReference||'')}</span><h2>${esc(entry.title||'Supplication')}</h2></div></div></div>${openDuaItems(entry).map((item,index)=>`<article class="panel library-dua-card"><div class="dua-card-head"><span class="dua-category-label">${esc(item.condition||'Recitation')}${item.count?` · ${esc(item.count)}×`:''}</span><button class="dua-bookmark ${state.savedDuas?.includes(`${identity}-${index}`)?'saved':''}" data-save-dua="${esc(`${identity}-${index}`)}" aria-label="Save this supplication">${state.savedDuas?.includes(`${identity}-${index}`)?'♥':'♡'}</button></div><p class="dua-arabic" lang="ar" dir="rtl">${esc(item.dua.arabic||'')}</p>${item.dua.transliteration?`<p class="library-translit">${esc(item.dua.transliteration)}</p>`:''}<p class="dua-meaning">${esc(item.dua.translation||'')}</p></article>`).join('')||'<div class="empty-state"><h3>Text details unavailable</h3><p>The source did not provide a recitation segment for this entry.</p></div>'}<details class="adhkar-evidence"><summary>References and source information</summary><p>Collection: Hisn al-Muslim by Saʿid ibn Ali ibn Wahf al-Qahtani · entry ${esc(entry.sourceReference||'not numbered')}</p>${references.map(ref=>`<p>${esc(typeof ref==='string'?ref:ref.title||ref.name||ref.reference||JSON.stringify(ref))}</p>`).join('')||'<p>The bundled catalogue does not provide a separate citation for this entry. It is presented as a numbered Hisn al-Muslim entry, not as an independently graded hadith.</p>'}</details><p class="learn-source-note">OpenDua dataset v0.0.4 · English, transliteration, editorial metadata, and data structure licensed CC BY 4.0. <a href="https://opendua.org/methodology" target="_blank" rel="noopener noreferrer">Methodology</a></p></section>`;
  }
  function renderDuaLearn(){
    const query=duaSearch.trim();
    const chapters=Array.isArray(duaChapters)?duaChapters:[];
    const searchMode=Boolean(query);
    const chapter=chapters.find(item=>(item.id||item.chapterId)===duaSelectedChapter);
    const currentEntries=searchMode?(duaSearchResults||[]):duaEntries;
    let content='';
    if(duaEntryDetail)content=renderOpenDuaDetail(duaEntryDetail);
    else if(duaLoading)content='<div class="panel content-loading"><span class="loading-spinner"></span><p>Loading sourced supplications…</p></div>';
    else if(duaError)content=renderSourceError(duaError,'data-retry-duas');
    else if(searchMode)content=`<div class="section-heading dua-results-heading"><div><h2>Search results</h2><p>${currentEntries.length} source matches</p></div></div><div class="library-collection-grid">${currentEntries.map(renderOpenDuaSummary).join('')||'<div class="empty-state"><h3>No matches found</h3><p>Try an Arabic or English phrase.</p></div>'}</div>`;
    else if(chapter)content=`<div class="library-detail-head"><button class="button secondary" data-dua-chapter-back>← All du’a chapters</button><div class="collection-detail-title"><span class="collection-illustration art-book">${libraryArtwork('book')}</span><div><span class="eyebrow">HISN AL-MUSLIM</span><h2>${esc(chapter.title||chapter.name||'Chapter')}</h2></div></div></div><div class="library-collection-grid">${currentEntries.map(renderOpenDuaSummary).join('')||'<div class="empty-state"><h3>No entries found in this chapter</h3></div>'}</div>`;
    else if(chapters.length)content=`<div class="dua-feature-banner"><span class="dua-banner-art">${libraryArtwork('sparkle')}</span><div><span class="eyebrow">HISN AL-MUSLIM · COMPLETE COLLECTION</span><h2>Supplications for everyday life</h2><p>Browse chapters, then open an entry for its Arabic, English meaning, transliteration, repetition details, and source information.</p></div></div><div class="library-heading"><div><span class="eyebrow">BROWSE THE COLLECTION</span><h2>${chapters.length} chapters</h2></div></div><div class="dua-categories">${chapters.map((item,index)=>{const id=item.id||item.chapterId;const art=['sun','moon','home','travel','shield','people','flower','compass'][index%8];return `<button class="dua-category ${duaSelectedChapter===id?'selected':''}" data-dua-chapter="${esc(id)}"><span class="collection-illustration art-${art}">${libraryArtwork(art)}</span><strong>${esc(item.title||item.name||item.chapterName||'Chapter')}</strong><small>${esc(item.entryCount?`${item.entryCount} entries`:'Read chapter')}</small><i>›</i></button>`}).join('')}</div>`;
    else content='<div class="panel content-loading"><span class="loading-spinner"></span><p>Loading Hisn al-Muslim chapters…</p></div>';
    return `<div class="page dua-page">${learnHeader('Du’a','Explore the full Hisn al-Muslim collection with sourced Arabic, meaning, and transliteration.')}<form class="spiritual-search" data-dua-search-form><span>⌕</span><input name="query" type="search" value="${esc(duaSearch)}" placeholder="Search Arabic or English…" aria-label="Search Hisn al-Muslim"><button class="sr-only" type="submit">Search</button></form>${content}<p class="learn-source-note">The complete OpenDua Hisn al-Muslim catalogue is bundled with Barakah for reliable offline loading. English, transliteration, editorial metadata, and dataset structure are CC BY 4.0; entry references are shown only where supplied. <a href="https://opendua.org/methodology" target="_blank" rel="noopener noreferrer">Source methodology</a> · <a href="https://opendua.org/licence/data" target="_blank" rel="noopener noreferrer">Data license</a>.</p></div>`;
  }
  function renderLearnNotes(){
    const notes=Array.isArray(state.learnNotes)?state.learnNotes:[]; state.learnNotes=notes;
    const editing=editingNoteId?notes.find(item=>item.id===editingNoteId):null;
    return `<div class="page">${learnHeader('Notes','Private reflections saved with your Barakah account.')}<section class="panel note-editor"><div class="panel-head"><div><h3>${editing?'Edit reflection':'Write a reflection'}</h3><p>Capture a thought, lesson, or intention from your journey.</p></div></div><form data-note-form><label class="sr-only" for="note-title">Note title</label><input id="note-title" name="title" class="text-input" maxlength="80" placeholder="A short title" value="${esc(editing?.title||'')}" required><label class="sr-only" for="note-body">Your reflection</label><textarea id="note-body" name="body" class="text-input note-body" maxlength="4000" placeholder="Write your reflection…" required>${esc(editing?.body||'')}</textarea><div class="note-form-actions">${editing?'<button class="button secondary" type="button" data-cancel-note>Cancel edit</button>':''}<button class="button primary" type="submit">${editing?'Save changes':'Save note'}</button></div></form></section><div class="section-heading"><div><h2>Your reflections</h2><p>${notes.length} ${notes.length===1?'note':'notes'}</p></div></div><div class="note-list">${notes.slice().sort((a,b)=>new Date(b.updatedAt||b.createdAt||0)-new Date(a.updatedAt||a.createdAt||0)).map(note=>`<article class="panel note-card"><div class="note-card-head"><div><h3>${esc(note.title)}</h3><time>${esc(new Date(note.updatedAt||note.createdAt||Date.now()).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}))}</time></div><div class="manage-actions"><button class="small-action" data-edit-note="${esc(note.id)}" aria-label="Edit ${esc(note.title)}" title="Edit">✎</button><button class="small-action delete" data-delete-note="${esc(note.id)}" aria-label="Delete ${esc(note.title)}" title="Delete">×</button></div></div><p>${esc(note.body).replace(/\n/g,'<br>')}</p></article>`).join('')||'<div class="empty-state"><div class="empty-icon">✧</div><h3>Your reflections start here</h3><p>Write down something you want to remember from today.</p></div>'}</div></div>`;
  }
  function bindLearn(){
    document.querySelectorAll('[data-learn-section]').forEach(button=>button.onclick=()=>{learnSection=button.dataset.learnSection;editingNoteId=null;render()});
    document.querySelectorAll('[data-learn-back]').forEach(button=>button.onclick=()=>{learnSection='hub';editingNoteId=null;render()});
    document.querySelectorAll('[data-dhikr-group]').forEach(button=>button.onclick=()=>{dhikrGroup=button.dataset.dhikrGroup;dhikrCollection='';dhikrSearch='';if(dhikrGroup==='prophetic'&&!propheticCollection)loadPropheticCollection().then(renderIfLearn).catch(renderIfLearn);render()});
    document.querySelectorAll('[data-dhikr-collection]').forEach(button=>button.onclick=()=>{dhikrCollection=button.dataset.dhikrCollection;duaEntries=[];loadDuaEntries(dhikrCollection)});
    document.querySelector('[data-dhikr-back]')?.addEventListener('click',()=>{dhikrCollection='';duaEntries=[];duaError='';render()});
    document.querySelector('[data-retry-adhkar]')?.addEventListener('click',()=>{adhkarPromise=null;loadAdhkarSource().then(renderIfLearn).catch(renderIfLearn)});
    document.querySelector('[data-retry-prophetic]')?.addEventListener('click',()=>{propheticPromise=null;propheticCollection=null;loadPropheticCollection().then(renderIfLearn).catch(renderIfLearn)});
    document.querySelector('[data-retry-occasions]')?.addEventListener('click',()=>{duaChaptersPromise=null;duaChapters=null;loadDuaChapters().then(renderIfLearn).catch(renderIfLearn)});
    document.querySelectorAll('[data-adhkar-count]').forEach(button=>button.onclick=()=>{state.adhkarCounts ||= {};const todayKey=dayKey(today);state.adhkarCounts[todayKey] ||= {};state.adhkarCounts[todayKey][button.dataset.adhkarCount]=(Number(state.adhkarCounts[todayKey][button.dataset.adhkarCount])||0)+1;save();render()});
    const dhikrInput=document.querySelector('[data-dhikr-search-form] input');
    document.querySelector('[data-dhikr-search-form]')?.addEventListener('submit',event=>{event.preventDefault();dhikrSearch=event.currentTarget.elements.query.value.trim();render()});
    dhikrInput?.addEventListener('input',()=>{dhikrSearch=dhikrInput.value;const caret=dhikrInput.selectionStart;render();const next=document.querySelector('[data-dhikr-search-form] input');next?.focus();next?.setSelectionRange(caret,caret)});
    document.querySelectorAll('[data-dua-chapter]').forEach(button=>button.onclick=()=>{duaSelectedChapter=button.dataset.duaChapter;duaEntries=[];duaEntryDetail=null;loadDuaEntries(duaSelectedChapter)});
    document.querySelector('[data-dua-chapter-back]')?.addEventListener('click',()=>{duaSelectedChapter='';duaEntries=[];duaEntryDetail=null;duaError='';render()});
    document.querySelector('[data-dua-detail-back]')?.addEventListener('click',()=>{duaEntryDetail=null;duaLoading=false;duaError='';render()});
    document.querySelectorAll('[data-open-dua]').forEach(button=>button.onclick=()=>loadDuaDetail(button.dataset.openDua));
    document.querySelector('[data-retry-duas]')?.addEventListener('click',()=>{duaError='';if(duaSearch.trim())searchDuaSource(duaSearch);else if(duaSelectedChapter)loadDuaEntries(duaSelectedChapter);else{duaChaptersPromise=null;duaChapters=null;loadDuaChapters().then(renderIfLearn).catch(renderIfLearn)}});
    const duaInput=document.querySelector('[data-dua-search-form] input');
    document.querySelector('[data-dua-search-form]')?.addEventListener('submit',event=>{event.preventDefault();duaSearch=event.currentTarget.elements.query.value.trim();duaSelectedChapter='';searchDuaSource(duaSearch)});
    duaInput?.addEventListener('input',()=>{duaSearch=duaInput.value;duaSelectedChapter='';duaEntryDetail=null;duaSearchResults=null;clearTimeout(duaSearchTimer);const caret=duaInput.selectionStart;render();const next=document.querySelector('[data-dua-search-form] input');next?.focus();next?.setSelectionRange(caret,caret);if(duaSearch.trim().length>=2)duaSearchTimer=setTimeout(()=>searchDuaSource(duaSearch),450);else if(!duaSearch.trim())renderIfLearn()});
    document.querySelectorAll('[data-save-dua]').forEach(button=>button.onclick=()=>{state.savedDuas ||= [];const ref=button.dataset.saveDua;state.savedDuas=state.savedDuas.includes(ref)?state.savedDuas.filter(item=>item!==ref):[...state.savedDuas,ref];save();render()});
    document.querySelector('[data-note-form]')?.addEventListener('submit',event=>{event.preventDefault();const title=event.currentTarget.elements.title.value.trim(),body=event.currentTarget.elements.body.value.trim();if(!title||!body)return;state.learnNotes ||= [];const now=new Date().toISOString();if(editingNoteId){const note=state.learnNotes.find(item=>item.id===editingNoteId);if(note){note.title=title;note.body=body;note.updatedAt=now}}else state.learnNotes.push({id:'note-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),title,body,createdAt:now,updatedAt:now});editingNoteId=null;save();toast('Reflection saved');render()});
    document.querySelectorAll('[data-edit-note]').forEach(button=>button.onclick=()=>{editingNoteId=button.dataset.editNote;render();$('#note-title')?.focus()});
    document.querySelectorAll('[data-delete-note]').forEach(button=>button.onclick=()=>{state.learnNotes=(state.learnNotes||[]).filter(note=>note.id!==button.dataset.deleteNote);if(editingNoteId===button.dataset.deleteNote)editingNoteId=null;save();toast('Note deleted');render()});
    document.querySelector('[data-cancel-note]')?.addEventListener('click',()=>{editingNoteId=null;render()});
    if(learnSection==='dhikr'){
      if((dhikrGroup==='morning'||dhikrGroup==='evening')&&!adhkarRecords&&!adhkarError)loadAdhkarSource().then(renderIfLearn).catch(renderIfLearn);
      if(dhikrGroup==='prophetic'&&!propheticCollection&&!propheticError)loadPropheticCollection().then(renderIfLearn).catch(renderIfLearn);
    }
    if(learnSection==='dua'&&!duaChapters&&!duaError)loadDuaChapters().then(renderIfLearn).catch(renderIfLearn);
  }
  function getLast7(){return Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(6-i));return {date:d,key:dayKey(d),label:d.toLocaleDateString(undefined,{weekday:'short'})}})}
  function renderInsights(){
    const days=getLast7(), totalPossible=state.habits.length*7, done=days.reduce((n,d)=>n+completedCount(d.key),0), rate=totalPossible?Math.round(done/totalPossible*100):0;
    const previous=days.slice(0,6).reduce((n,d)=>n+completedCount(d.key),0), best=Math.max(0,...days.map(d=>completedCount(d.key)));
    const cats=[...new Set(state.habits.map(h=>h.category))].slice(0,5).map(cat=>{const items=state.habits.filter(h=>h.category===cat);const c=days.reduce((n,d)=>n+items.filter(h=>getStatus(d.key,h.id)==='done').length,0);return {cat,pct:items.length?Math.round(c/(items.length*7)*100):0}});
    const hist=state.habits.slice(0,6).map(h=>`<div class="history-row"><span>${esc(h.name)}</span>${days.map(d=>{const s=getStatus(d.key,h.id);return `<span class="history-dot ${s==='done'?'high':s==='partial'?'mid':''}" title="${esc(d.label)} · ${s||'not logged'}"></span>`}).join('')}</div>`).join('');
    return `<div class="page"><div class="page-title"><div><span class="eyebrow">YOUR JOURNEY, IN PERSPECTIVE</span><h1>Small steps, <span style="color:#9eaa74">steady growth.</span></h1><p class="subheading">A kind look at your practice over the last seven days.</p></div></div>
    <div class="stats-grid"><div class="stat-card"><span class="stat-label">Intentions kept</span><strong>${rate}%</strong><small>of your weekly check-ins</small></div><div class="stat-card"><span class="stat-label">Practices today</span><strong>${completedCount(dayKey(today))}<span style="color:#a0a99b;font-size:13px"> / ${state.habits.length}</span></strong><small>small steps add up</small></div><div class="stat-card"><span class="stat-label">Best day this week</span><strong>${best}</strong><small>intentions completed</small></div><div class="stat-card"><span class="stat-label">Active intentions</span><strong>${state.habits.length}</strong><small>your personal practice</small></div></div>
    <div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h3>Your consistency</h3><p>Daily practices completed</p></div><select class="range-select" aria-label="Chart range"><option>Last 7 days</option></select></div><div class="chart-wrap"><canvas id="trend-chart" aria-label="Habit completion trend for the last seven days"></canvas></div></section><section class="panel"><div class="panel-head"><div><h3>By intention</h3><p>Weekly completion by category</p></div></div><div class="category-bars">${cats.length?cats.map(c=>`<div class="category-row"><span>${esc(c.cat)}</span><div class="category-track"><div class="category-fill" style="width:${c.pct}%"></div></div><b>${c.pct}%</b></div>`).join(''):`<p class="subheading">Add habits to see your category trends.</p>`}</div><div class="insight-note"><span>✦</span><p><strong>${rate>=70?'Consistency is taking root.':rate>0?'Every check-in is a beginning.':'Start where you are.'}</strong> ${rate>=70?'Your regular effort is a beautiful thing to notice.':rate>0?'Notice what feels supportive and keep returning to it.':'Choose one small practice for today.'}</p></div></section></div>
    <section class="panel history-panel"><div class="panel-head"><div><h3>Practice rhythm</h3><p>Each square is one day of your journey</p></div></div><div class="history-row history-header"><span>Habit</span>${days.map(d=>`<span style="text-align:center">${d.label.slice(0,1)}</span>`).join('')}</div>${hist||'<p class="subheading">Create a habit to begin your history.</p>'}</section>
    </div>`;
  }
  function renderHabits(){return `<div class="page"><div class="page-title"><div><span class="eyebrow">SHAPE A PRACTICE THAT FITS YOU</span><h1>Your intentions<span style="color:#9eaa74">.</span></h1><p class="subheading">Add, edit, or let go of habits as your journey evolves.</p></div><button class="button primary" data-action="add">＋ Add habit</button></div><div class="section-heading" style="margin-top:0"><div><h2>${state.habits.length} ${state.habits.length===1?'intention':'intentions'}</h2><p>Your practices are personal and can change over time.</p></div></div><div class="habits-manage">${state.habits.map(h=>`<article class="manage-card"><div class="habit-symbol">${esc(h.icon)}</div><div class="habit-info"><strong>${esc(h.name)}</strong><span>${esc(h.category)}${h.goal?' · '+esc(h.goal):''}</span></div><div class="manage-actions"><button class="small-action" data-edit="${esc(h.id)}" aria-label="Edit ${esc(h.name)}" title="Edit">✎</button><button class="small-action delete" data-delete="${esc(h.id)}" aria-label="Delete ${esc(h.name)}" title="Delete">×</button></div></article>`).join('')||`<div class="empty-state"><div class="empty-icon">✧</div><h3>Your journey starts here</h3><p>Add a meaningful practice to begin building your personal tracker.</p><button class="button primary" data-action="add">Add your first habit <span>↗</span></button></div>`}</div><div class="panel" style="margin-top:18px"><div class="insight-note" style="margin:0"><span>♡</span><p><strong>Make room for what matters.</strong> A good habit is one that brings meaning to your own life. Keep it small enough to return to.</p></div></div></div>`}
  function renderProfile(){const user=window.BARAKAH_USER,name=user?.user_metadata?.full_name||user?.email?.split('@')[0]||'Your profile',loc=state.profile?.location||{},created=user?.created_at?new Date(user.created_at).toLocaleDateString(undefined,{month:'long',year:'numeric'}):'—';return `<div class="page"><div class="page-title"><div><span class="eyebrow">YOUR SPACE, YOUR PACE</span><h1>Profile<span style="color:#9eaa74">.</span></h1><p class="subheading">Your account, preferences, and spiritual journey settings.</p></div></div><section class="panel profile-panel"><div class="profile-large"><div class="avatar" lang="ar" dir="rtl">${esc(arabicInitial(name))}</div><div><h2>${esc(name)}</h2><p>${esc(user?.email||'Signed in to Barakah')}</p></div></div><div class="profile-actions"><button class="button secondary" data-goto="insights">View spiritual analytics ↗</button><button class="button secondary" data-profile-signout>Sign out</button></div></section><section class="panel profile-settings"><div class="panel-head"><div><h3>Account details</h3><p>Update the name used to greet you across Barakah.</p></div></div><div class="profile-fields"><label class="field-label" for="profile-name-input">Display name</label><input id="profile-name-input" class="text-input" maxlength="60" value="${esc(name)}"/><label class="field-label" for="profile-email">Email address</label><input id="profile-email" class="text-input" value="${esc(user?.email||'') }" readonly/><div class="profile-account-meta"><span>Account created</span><strong>${esc(created)}</strong></div><button class="button primary" data-save-profile>Save profile</button></div></section><section class="panel profile-settings appearance-settings"><div class="panel-head"><div><h3>Appearance</h3><p>Choose the theme that feels comfortable for your journey.</p></div></div><div class="profile-fields"><label class="field-label" for="appearance-select">Color theme</label><select id="appearance-select" class="text-input"><option value="light" ${state.appearance==='light'?'selected':''}>Light</option><option value="dark" ${state.appearance==='dark'?'selected':''}>Dark</option></select></div></section><section class="panel profile-settings"><div class="panel-head"><div><h3>Prayer times</h3><p>Choose a location and calculation convention for daily prayer times.</p></div></div><div class="profile-fields"><label class="field-label" for="prayer-city">City</label><input id="prayer-city" class="text-input" value="${esc(loc.city||'')}" placeholder="e.g. Bengaluru"/><label class="field-label" for="prayer-country">Country</label><input id="prayer-country" class="text-input" value="${esc(loc.country||'')}" placeholder="e.g. India"/><label class="field-label" for="prayer-method">Calculation method</label><select id="prayer-method" class="text-input"><option value="3" ${String(loc.method||3)==='3'?'selected':''}>Muslim World League</option><option value="1" ${String(loc.method)==='1'?'selected':''}>University of Islamic Sciences, Karachi</option><option value="2" ${String(loc.method)==='2'?'selected':''}>ISNA</option><option value="4" ${String(loc.method)==='4'?'selected':''}>Umm Al-Qura, Makkah</option><option value="5" ${String(loc.method)==='5'?'selected':''}>Egyptian General Authority</option></select><button class="button primary" data-save-location>Save prayer location</button></div></section><section class="panel profile-settings"><div class="panel-head"><div><h3>Qur’an reading</h3><p>Your reading position and saved ayahs sync with your Barakah account.</p></div></div><div class="insight-note" style="margin:0"><span>۞</span><p><strong>${state.quran?.progress?'Last read: '+esc(state.quran.progress.surahName)+' · ayah '+state.quran.progress.ayah:'Start your reading journey.'}</strong> Your current reading position is saved whenever you open an ayah.</p></div><button class="button secondary" data-goto="quran" style="margin-top:14px">Open Qur’an reader ↗</button></section></div>`}
  function bindView(){
    document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;render()});
    document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{activeView=b.dataset.goto;render()});
    document.querySelectorAll('[data-action="add"]').forEach(b=>b.onclick=()=>openDialog());
    document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const id=b.dataset.check;setStatus(selectedDate,id,getStatus(selectedDate,id)==='done'?'':'done');render()});
    document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const d=selected();d.setDate(d.getDate()+Number(b.dataset.day));if(dayKey(d)<=dayKey(today)){selectedDate=dayKey(d);render()}});
    document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openDialog(b.dataset.edit));
    document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteHabit(b.dataset.delete));
    document.querySelector('#appearance-select')?.addEventListener('change',event=>{state.appearance=event.target.value==='dark'?'dark':'light';document.documentElement.dataset.theme=state.appearance;save();toast(state.appearance==='dark'?'Dark appearance enabled':'Light appearance enabled')});
    document.querySelectorAll('[data-profile-signout]').forEach(b=>b.onclick=async()=>{if(!window.BARAKAH_SIGNOUT)return;if(!confirm('Sign out of your Barakah account?'))return;try{await window.BARAKAH_SIGNOUT()}catch{toast('Could not sign out. Please try again.')}});
    document.querySelector('[data-save-profile]')?.addEventListener('click',async()=>{const input=$('#profile-name-input'),name=input.value.trim();if(!name){toast('Enter a display name.');input.focus();return}if(!window.BARAKAH_UPDATE_PROFILE){toast('Profile updates require an account.');return}const button=$('[data-save-profile]');button.disabled=true;try{await window.BARAKAH_UPDATE_PROFILE(name);toast('Profile name updated');render()}catch(error){toast(error?.message||'Could not update your profile.')}finally{button.disabled=false}});
  }
  function openDialog(id=null){editingId=id;const h=id?state.habits.find(x=>x.id===id):null;$('#dialog-title').textContent=h?'Edit habit':'Create a habit';$('#habit-name').value=h?.name||'';$('#habit-category').value=h?.category||'Prayer';$('#habit-goal').value=h?.goal||'';selectedIcon=h?.icon||iconSet[0];$('#save-habit').innerHTML=h?'Save changes <span>↗</span>':'Save habit <span>↗</span>';$('#icon-choices').innerHTML=iconSet.map(icon=>`<button type="button" class="icon-choice ${icon===selectedIcon?'selected':''}" data-icon="${icon}" aria-label="Choose ${icon}">${icon}</button>`).join('');document.querySelectorAll('[data-icon]').forEach(b=>b.onclick=()=>{selectedIcon=b.dataset.icon;document.querySelectorAll('[data-icon]').forEach(x=>x.classList.toggle('selected',x===b))});$('#habit-dialog').showModal();setTimeout(()=>$('#habit-name').focus(),60)}
  function deleteHabit(id){const h=state.habits.find(x=>x.id===id);if(!h)return;if(!confirm(`Remove “${h.name}” and its check-in history?`))return;state.habits=state.habits.filter(x=>x.id!==id);Object.values(state.logs).forEach(log=>delete log[id]);save();render();toast('Habit removed')}
  function drawChart(){const canvas=$('#trend-chart');if(!canvas)return;const dark=document.documentElement.dataset.theme==='dark',grid=dark?'#2d3a30':'#edf0e9',label=dark?'#a5b2a5':'#a0a69b',line=dark?'#a3bb8d':'#83946d',pointFill=dark?'#19221c':'#fff';const box=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=box.width*dpr;canvas.height=box.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=box.width,h=box.height,days=getLast7(),max=Math.max(3,state.habits.length),left=26,right=12,top=12,bottom=27,cw=w-left-right,ch=h-top-bottom;ctx.font='9px DM Sans';ctx.textBaseline='middle';for(let i=0;i<=3;i++){const y=top+ch-(ch*i/3);ctx.strokeStyle=grid;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle=label;ctx.textAlign='right';ctx.fillText(Math.round(max*i/3),left-8,y)}const points=days.map((d,i)=>({x:left+(days.length===1?0:cw*i/(days.length-1)),y:top+ch-(completedCount(d.key)/max)*ch,label:d.label}));ctx.strokeStyle=line;ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();points.forEach(p=>{ctx.fillStyle=pointFill;ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle=line;ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=label;ctx.textAlign='center';ctx.fillText(p.label,p.x,h-10)})}
  $('#habit-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#habit-name').value.trim();if(!name)return;const payload={name,category:$('#habit-category').value,goal:$('#habit-goal').value.trim(),icon:selectedIcon};if(editingId){Object.assign(state.habits.find(h=>h.id===editingId),payload);toast('Habit updated')}else{state.habits.push({id:crypto.randomUUID?.()||String(Date.now()),...payload});toast('A new intention begins')}save();$('#habit-dialog').close();render()});
  $('#close-dialog').onclick=()=>$('#habit-dialog').close();$('#cancel-dialog').onclick=()=>$('#habit-dialog').close();
  $('#today-button').onclick=()=>{selectedDate=dayKey(today);activeView='today';render()};
  window.addEventListener('resize',()=>{if(activeView==='insights')drawChart()});
  render();
})();
